import { isValidObjectId } from "mongoose";
import { Vehicle } from "../../Models/vehicle.model.js";

export const addVehicle = async (req, res) => {
  try {
    const { name, brand, color, status, model, seat_no } = req.body;

    if (!name) {
      return res.status(404).json({
        message: "Enter Vehicle Name",
        success: false
      })
    } else if (!brand) {
      return res.status(404).json({
        message: "Enter Brand Name",
        success: false
      })
    } else if (!color) {
      return res.status(404).json({
        message: "Enter Color Name",
        success: false
      })
    } else if (!model) {
      return res.status(404).json({
        message: "Enter Model Name",
        success: false
      })
    } else if (!seat_no) {
      return res.status(404).json({
        message: "Enter Seat No.",
        success: false
      })
    }

    const data = { name, brand, color, status, model, seat_no };
    const response = new Vehicle(data);
    await response.save();
    res.status(200).json({
      message: "Vehicle added successfully",
      success: true,
      data: response
    });
  } catch (error) {
    console.log(error);
    return res.status(404).json({
      message: "Error while adding vehicle",
      success: false,
      error: error.message
    })
  }
}



export const viewVehicles = async (req, res) => {
  try {
    const allVehicles = await Vehicle.find();
    return res.status(200).json({
      message: "All data fetched",
      success: true,
      data: allVehicles
    })
  } catch (error) {
    return res.status(404).json({
      message: "Error while fetching data",
      success: false
    })
  }
}




export const editVehicleById = async (req, res) => {
  try {
    const { id } = req.params;
    if (!isValidObjectId(id)) {
      return res.status(404).json({
        message: "Invalid Object Id",
        success: false
      })
    }

    const updatedData = {
      name: req.body.name,
      brand: req.body.brand,
      color: req.body.color,
      status: req.body.status,
      model: req.body.model,
      seat_no: req.body.seat_no,
    };
    const operation = await Vehicle.findByIdAndUpdate(id, updatedData, { new: true });
    if (!operation) {
      return res.status(404).json({
        message: "Data not exist in database",
        success: false
      })
    }
    return res.status(200).json({
      message: "Data Updated Successfully",
      success: true
    })

  } catch (error) {
    console.log(error);
    return res.status(404).json({
      message: "Error while updating data",
      success: false
    })
  }
}



