export const deleteVehicleById = async (req, res) => {
  try {
    const { id } = req.params;
    if (!isValidObjectId(id)) {
      res.status(404).json({
        message: "Object Id is not valid",
        success: false,
      });
    }
    const operation = await Vehicle.findById(id);
    if (!operation) {
      res.status(200).json({
        message: "Vehicle not exist in DB",
        success: false,
      });
    }
    const deleteData = await Vehicle.findByIdAndDelete(id);
    res.status(200).json({
      message: "Vehicle deleted Successfully",
      success: true,
    });
  } catch (error) {
    console.log("Error", error);
    res.status(200).json({
      message: "Error while deleting Vehicle",
      success: false,
    });
  }
}


export const vehicleList = async (req, res) => {
  try {
    const response = await Vehicle.find();
    if (!response) {
      return res.status(404).json({
        message: "Error Occur While fetching List Of Vehicles",
        success: false
      })
    }
    return res.status(200).json({
      message: "Vehicle List",
      data: response,
      success: true
    })
  } catch (error) {
    res.status(200).json({
      message: error.message,
      success: false,
    });
  }
}



export const ById = async (req, res) => {
  try {
    const { id } = req.params;
    const response = await Vehicle.find({ id });
    if (!response) {
      return res.status(404).json({
        message: "Error Occur While fetching Vehicles",
        success: false
      })
    }
    return res.status(200).json({
      message: "Vehicle Data",
      data: response,
      success: true
    })
  } catch (error) {
    res.status(200).json({
      message: error.message,
      success: false,
    });
  }
}


